/** Splits one locale's encoded rows back apart. */
private fun decodeTimeZoneGoldenRows(record: String): List<IcuTimeZoneGoldenRow> =
    record.split('\u001E').map { row ->
        val fields = row.split('\u001F')
        IcuTimeZoneGoldenRow(
            zoneId = fields[0],
            epochSeconds = fields[1].toLong(),
            offsetSeconds = fields[2].toInt(),
            daylight = fields[3] == "1",
            names = fields.subList(4, fields.size),
        )
    }
